  reg [63:0] win_lfsr = 64'h1D2CACE15EED0001;
  reg [6:0] u = 0;
  reg [15871:0] rec = 0;
  localparam REC = 0, SEND = 1;
  reg state = REC;

  function [7:0] hex(input [3:0] v);
    hex = v < 10 ? 8'h30 + v : 8'h37 + v;
  endfunction

  reg [11:0] ci = 0;
  reg [7:0] ch;
  always @* begin
    if (ci == 0) ch = "R";
    else if (ci < 17) ch = hex(win_lfsr[63 - 4 * (ci - 1) -: 4]);
    else if (ci < 3985) ch = hex(rec[15871 -: 4]);
    else if (ci == 3985) ch = 8'h0d;
    else ch = 8'h0a;
  end

  reg tx = 1, busy = 0;
  reg [7:0] baud = 0;
  reg [3:0] bitn = 0;
  reg [9:0] shift = 10'h3ff;

  always @(posedge clk_25mhz) begin
    lfsr <= step_lfsr(lfsr);
    case (state)
      REC: begin
        if (u == 0) win_lfsr <= lfsr;
        rec <= {rec[15747:0], s};
        u <= u + 1;
        if (u == 127) begin
          state <= SEND;
          u <= 0;
        end
      end
      SEND:
