          tx <= shift[0];
          shift <= {1'b1, shift[9:1]};
          bitn <= bitn + 1;
          if (bitn == 9) begin
            busy <= 0;
            if (ci >= 17 && ci < 3985)
              rec <= {rec[15867:0], rec[15871 -: 4]};
            if (ci == 3986) begin
              ci <= 0;
              state <= SEND;
            end else ci <= ci + 1;
          end
        end else baud <= baud + 1;
    endcase
  end

